INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('7b42367a-9fa4-4055-a9c5-128c77c48563', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '12', '11. Project Plan (native milestone table: Name/Desc/Timeframe/Funds/Vendor; funds sum to ask)', '{"version":2,"document_id":"3bcc160b-3ae7-48c1-9b54-5314e866c119","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"11. Project Plan (native milestone table: Name/Desc/Timeframe/Funds/Vendor; funds sum to ask)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.057Z","last_modified_at":"2026-08-10T12:11:27.057Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n307ccbcf","type":"heading","content":{"level":1,"text":"11. Project Plan"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n3f3b01ce","type":"text_block","content":{"text":"The 14-month effort takes the printer to a production-representative unit with independent performance validation. Milestones are measurable and map one-for-one to the Q3 Gantt; funds shown are TVSF/OTF unless noted as blended grant/VC."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n2ddeb2f7","type":"table","content":{"headers":[{"text":"Milestone","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"Description / Success Criteria","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"Timeframe","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"Funds","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}}],"rows":[[{"text":"Hire core team"},{"text":"Fill technician/operator roles — team in place"},{"text":"Months 1–2"},{"text":"$10,000"}],[{"text":"R&D with Converge"},{"text":"Engineer the beta printer + delivery/gate — validated subsystem specs"},{"text":"Months 3–4"},{"text":"$190,000"}],[{"text":"Beta prototype build"},{"text":"Assemble the first field-representative printer — prints a test wall to spec"},{"text":"Months 6–8"},{"text":"(within R&D)"}],[{"text":"Third-party performance validation"},{"text":"Independent structural + throughput test — passing validation report"},{"text":"Months 9–14"},{"text":"~$30,000"}],[{"text":"First printer build"},{"text":"Production-representative unit for pilots — pilot-ready printer"},{"text":"Months 11–14"},{"text":"~$300,000 (blended)"}]]},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n62f8d891","type":"text_block","content":{"text":"The plan is sequenced around two decision points: after R&D with Converge (validated subsystem specs) before committing to the field-representative build, and after third-party validation before the production-representative first printer. Converge provides fixed-scope development services and a software-development partner supports the print pipeline, bounding schedule and budget risk."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T12:11:28.498Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T12:11:28.498Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T12:11:28.498Z'::timestamptz, true, '2026-08-10T12:11:28.498Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 12, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('242cb813-d082-48f5-b228-782075e9fc79', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '10', '9. Management Team (highest-weighted; names, FTE %, $ raised across ventures)', '{"version":2,"document_id":"8b168256-495a-4762-932a-67c5a8bb3a16","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"9. Management Team (highest-weighted; names, FTE %, $ raised across ventures)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.055Z","last_modified_at":"2026-08-10T12:11:27.055Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n1b44b386","type":"heading","content":{"level":1,"text":"9. Management Team"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"ncd6575b1","type":"text_block","content":{"text":"Foundation is led by its four founders, who own strategy, operations, finance, and the core printing technology:"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n5a9d6ae0","type":"bulleted_list","content":{"items":[{"text":"Kate Ulepic, Chief Executive Officer — leads strategy and fundraising."},{"text":"Conor Atkins, Chief Operations Officer — owns operations and print execution."},{"text":"Connor Casey, Chief Financial Officer — owns finance and the capital plan."},{"text":"Will Curley, Chief Technology Officer — owns the printer and delivery technology."}]},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"naf38aae4","type":"text_block","content":{"text":"The founding team has taken the printer to a beta prototype, so the technical risk sits with people who have already retired much of it. The team has identified its known gaps and is actively recruiting for them — a legal advisor, a fundraiser, a technician/operator, and a homebuilder partner — with the first technical hire funded in this project’s budget. Foundation is mentored through the Entrepreneurs’ Center (Paul Jackson, VP Strategic Programs), which has advised on customer discovery, the financial model, and this application. A founder team that has built a working prototype, a concrete plan to fill named gaps, and active EC mentorship together form the core of Foundation’s execution-risk mitigation — the highest-weighted TVSF review criterion."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T12:11:28.108Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T12:11:28.108Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T12:11:28.108Z'::timestamptz, true, '2026-08-10T12:11:28.108Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 10, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('e0a6c3eb-04c7-4ca6-96e4-b6edd232b5c8', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '15', '14. Major Risks & Mitigation (native Risk table: Risk/Type/Severity/Mitigation)', '{"version":2,"document_id":"af11e791-81ed-40d5-abab-3783fc06b37f","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"14. Major Risks & Mitigation (native Risk table: Risk/Type/Severity/Mitigation)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.060Z","last_modified_at":"2026-08-10T12:11:27.060Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n423dc2f2","type":"heading","content":{"level":1,"text":"14. Major Risks and Mitigation"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n454c490d","type":"text_block","content":{"text":"Foundation has structured the project so its principal risks are retired early and by evidence rather than assertion. The highest-consequence risks, their type and severity, and the specific mitigation:"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"ndb6f3774","type":"table","content":{"headers":[{"text":"Risk","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"Type","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"Severity","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"Mitigation","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}}],"rows":[[{"text":"Concrete-mix variability across regions"},{"text":"Technical"},{"text":"Medium"},{"text":"The external gate tolerates common local ready-mix; beta testing spans multiple locally batched designs."}],[{"text":"Code / inspection acceptance"},{"text":"Regulatory"},{"text":"High"},{"text":"Third-party structural + throughput validation (Months 9–14) produces a passing report ahead of pilots."}],[{"text":"Subcontractor / builder adoption inertia"},{"text":"Market"},{"text":"Medium"},{"text":"Printing-as-a-service removes the capital barrier; demos → pilots convert on proof, not promises."}],[{"text":"Beta-build / development execution"},{"text":"Execution"},{"text":"Medium"},{"text":"Fixed-scope Converge engagement + software partner; two milestone decision gates bound schedule and budget."}],[{"text":"Financing / dilution"},{"text":"Financial"},{"text":"Medium"},{"text":"Non-dilutive $200k TVSF + $150k SBIR de-risk the plan so the $1.8M equity round is priced on validated performance."}]]},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"ne699b8fc","type":"text_block","content":{"text":"Every claim in this application is converted into third-party evidence within the project: a production-representative printer, an independent validation report, and a pilot-ready unit. Foundation respectfully requests TVSF support to validate a technology that takes cost, labor, and schedule out of every home — built and manufactured in Ohio."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T12:11:28.679Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T12:11:28.679Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T12:11:28.679Z'::timestamptz, true, '2026-08-10T12:11:28.679Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 15, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('5ba5ea4c-6cc6-4b03-8b6e-8619b831706b', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '3', '2. Overview of Technology/Product (native competitor comparison table)', '{"version":2,"document_id":"a93b0b69-9d95-46b3-801d-99fd9c9c3430","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"2. Overview of Technology/Product (native competitor comparison table)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.045Z","last_modified_at":"2026-08-10T12:11:27.045Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n888d4b6e","type":"heading","content":{"level":1,"text":"2. Overview of Technology/Product"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"na367ebf9","type":"text_block","content":{"text":"Foundation’s system prints a home’s foundation-wall geometry directly: a plan is downloaded to the printer, concrete is pumped into the machine, and the nozzle lays concrete one layer at a time while a printing trolley moves laterally and vertically and the whole machine travels along runway rails; it is electrically powered. Two differentiators define the product. First, it uses common, locally sourced concrete rather than an expensive proprietary mortar. Second, an external gate controls material flow at the nozzle, producing clean starts, stops, and consistent layers. Together these eliminate the build-strip-repair-clean formwork cycle, saving ~311 labor hours per home and cutting production cost ~47–50%."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n5fa22542","type":"text_block","content":{"text":"Against the alternatives — traditional formwork and the leading 3D-construction printers ICON, COBOD International, and Apis Cor — Foundation is the only approach that pairs common, locally-batched concrete with the lowest project cost. ICON prints with a proprietary Lavacrete mortar, and COBOD and Apis Cor rely on their own specialized mixes; Foundation’s externally-gated nozzle runs on standard local ready-mix, which is a durable cost and supply-chain advantage no proprietary-material competitor can match. Builder demand for printed construction is already real and funded — D.R. Horton, the largest U.S. homebuilder, backed Apis Cor in 2024 — which de-risks Foundation’s market rather than its technology:"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n09c172b0","type":"table","content":{"headers":[{"text":"Dimension","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"Foundation","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"Traditional Formwork","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"ICON","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"COBOD","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"Apis Cor","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}}],"rows":[[{"text":"Speed / low labor"},{"text":"✓"},{"text":"✗"},{"text":"✓"},{"text":"✓"},{"text":"✓"}],[{"text":"On-site deployment"},{"text":"✓"},{"text":"✓"},{"text":"✓"},{"text":"✗"},{"text":"✓"}],[{"text":"Common local concrete (no proprietary mortar)"},{"text":"✓"},{"text":"✓"},{"text":"✗"},{"text":"✗"},{"text":"✗"}],[{"text":"Lowest project cost"},{"text":"✓"},{"text":"✗"},{"text":"✗"},{"text":"✗"},{"text":"✗"}],[{"text":"Scalable / repeatable"},{"text":"✓"},{"text":"✗"},{"text":"✓"},{"text":"✓"},{"text":"✓"}]]},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"nf2f2f128","type":"text_block","content":{"text":"Traditional formwork is slow and labor-heavy; ICON, COBOD, and Apis Cor print at scale but depend on costly proprietary materials rather than common, locally batched concrete — the constraint Foundation’s external gate removes, and the reason its per-job cost is the lowest in the field."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"ned047a9f","type":"text_block","content":{"text":"Competitor sources: SNS Insider and Kings Research 3D-construction-printing leader rankings (2026); ICON (Lavacrete), COBOD (BOD2/BOD3), Apis Cor / D.R. Horton 2024 investment — company and industry reporting."},"style":{"fontSize":8,"italic":true,"color":"#555555"},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false}]}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T16:18:55.315Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'final', '2026-08-10T16:18:55.315Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T16:18:55.315Z'::timestamptz, true, '2026-08-10T16:18:55.315Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 3, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('782cd6c7-9285-43de-bd39-247f812d2e40', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '2', '1. Market Opportunity (external only; state TAM; SAM/SOM; hyperlinks allowed here only)', '{"version":2,"document_id":"3b56c138-4ed5-40f4-a33c-cdec78ac75c3","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"1. Market Opportunity (external only; state TAM; SAM/SOM; hyperlinks allowed here only)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.043Z","last_modified_at":"2026-08-10T12:11:27.043Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"nf89f4403","type":"heading","content":{"level":1,"text":"1. Market Opportunity"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"nd9fb90c2","type":"text_block","content":{"text":"Every residential concrete foundation in the United States is formed with temporary formwork that must be built, set, stripped, repaired, and cleaned. On a 2,100 sq ft single-family home this cycle costs $20,000–$25,000 and roughly 336 labor hours, and it is a chronic source of schedule slip because it cannot proceed in poor weather. The pain is felt hardest by production homebuilders and their foundation subcontractors, who face a persistent skilled-labor shortage and a structural under-supply of entry-level housing — a roughly 500,000-home supply/demand gap that a 6% mortgage “lock-in” has only deepened."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n6b285e03","type":"text_block","content":{"text":"The U.S. single-family home construction market is about $846 billion in 2026 (up from $804 billion in 2025, ~5% CAGR) — the total market whose foundations Foundation’s technology touches (TAM). The specific spend category Foundation displaces, the U.S. concrete-formwork market, is roughly $2.3 billion — about 28% of the ~$8.2 billion global formwork market (SAM). Foundation’s near-term serviceable-obtainable market is about $27 million (SOM): a regional Ohio/Midwest ramp at approximately $20,000 per foundation and roughly 1,300 foundations per year within five years. The timing is set by a category inflecting now — the U.S. 3D-construction-printing market is roughly $5.35 billion in 2026 and growing on the order of 80% per year — so Foundation is entering an accelerating market, not creating demand from zero."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n88d2f6a8","type":"text_block","content":{"text":"Removing about 47% of the formwork cost and ~311 labor hours from every foundation — without asking the builder to change concrete supplier, code path, or crew skill profile — is therefore both economically compelling and timely. Foundation 3D printing reduces overall home cost by an estimated ~4%, directly addressing the affordability and skilled-labor pressures at the center of Ohio’s housing and advanced-manufacturing agendas."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n16958b37","type":"text_block","content":{"text":"Market sources: U.S. single-family construction — The Business Research Company / Research&Markets (2026). Concrete-formwork market — Cognitive Market Research & Persistence Market Research (global), U.S. ~28% share. 3D-construction-printing market — Fortune Business Insights (2026). SOM is a bottoms-up estimate from Foundation’s stated unit economics."},"style":{"fontSize":8,"italic":true,"color":"#555555"},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false}]}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T16:18:55.135Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'final', '2026-08-10T16:18:55.135Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T16:18:55.135Z'::timestamptz, true, '2026-08-10T16:18:55.135Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 2, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('6a15f4a7-b4a2-4ab9-b504-f5ee8d82833e', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '16', 'Budget (spend-type table; $200,000 cap; Personnel <= $40,000)', '{"version":1,"document_id":"4e70cfe5-42d7-4d7a-9c73-d43203418bf0","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":72,"right":72,"bottom":72,"left":72},"header":{"template":"Foundation — TVSF Budget","height":36,"font":{"family":"Times New Roman","size":10}},"footer":{"template":"Foundation — TVSF Application (confidential)","height":36,"font":{"family":"Times New Roman","size":10}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.15,"max_pages":null,"max_slides":null},"metadata":{"title":"Budget","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.061Z","last_modified_at":"2026-08-10T12:11:27.061Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"na032e1d7","type":"heading","content":{"level":1,"text":"Budget — Ohio Third Frontier TVSF"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"nc9ca6d19","type":"text_block","content":{"text":"Project budget by spend type. The OTF ask is exactly $200,000; Personnel is within the 20% share cap ($40,000); no applicant cost share is required or claimed."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n6a3f797b","type":"table","content":{"sheet_name":"Budget","is_spreadsheet":true,"headers":[{"text":"Spend Type","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"OTF Project Funds","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"Basis / Narrative","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}}],"rows":[[{"text":"Personnel","style":{"bold":true,"bg":"#e8e8e8"}},{"text":"$40,000","value":40000,"number_format":"$#,##0","cell_type":"currency","style":{"alignment":"right"}},{"text":"Founding-team time + the first technical hire against the beta build"}],[{"text":"Equipment","style":{"bold":true,"bg":"#e8e8e8"}},{"text":"$120,000","value":120000,"number_format":"$#,##0","cell_type":"currency","style":{"alignment":"right"}},{"text":"COTS + specialized printer/delivery parts for the beta prototype (built with Converge)"}],[{"text":"Supplies","style":{"bold":true,"bg":"#e8e8e8"}},{"text":"$10,000","value":10000,"number_format":"$#,##0","cell_type":"currency","style":{"alignment":"right"}},{"text":"Concrete + consumables to run prototype print tests"}],[{"text":"Purchased Services","style":{"bold":true,"bg":"#e8e8e8"}},{"text":"$30,000","value":30000,"number_format":"$#,##0","cell_type":"currency","style":{"alignment":"right"}},{"text":"Converge development services + a software-development partner"}],[{"text":"Total OTF Project Funds","style":{"bg":"#DCE6F1","bold":true}},{"text":"$200,000","value":200000,"number_format":"$#,##0","cell_type":"currency","style":{"alignment":"right","bg":"#DCE6F1","bold":true}},{"text":"","style":{"bg":"#DCE6F1","bold":true}}]],"column_widths":[150,110,270],"border_style":"single"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n2feeea60","type":"heading","content":{"level":2,"text":"Budget Compliance"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n4b42ebfb","type":"table","content":{"is_spreadsheet":true,"headers":[{"text":"Metric","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"Value","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"Requirement","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"Status","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}}],"rows":[[{"text":"OTF Ask"},{"text":"$200,000","value":200000,"number_format":"$#,##0","cell_type":"currency","style":{"alignment":"right"}},{"text":"≤ $200,000"},{"text":"PASS","style":{"bold":true}}],[{"text":"Personnel Share"},{"text":"20.0%","value":0.2,"number_format":"0.0%","cell_type":"percent","style":{"alignment":"right"}},{"text":"≤ 20%"},{"text":"PASS","style":{"bold":true}}],[{"text":"Applicant Cost Share"},{"text":"$0","value":0,"number_format":"$#,##0","cell_type":"currency","style":{"alignment":"right"}},{"text":"None required"},{"text":"PASS","style":{"bold":true}}]],"column_widths":[150,90,160,70],"border_style":"single"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"nce07e31e","type":"heading","content":{"level":2,"text":"Budget Narrative"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n4c940571","type":"text_block","content":{"text":"The grant is concentrated on Equipment ($120,000) — COTS and specialized printer/delivery parts to build the beta prototype with Converge — and Purchased Services ($30,000) for Converge’s engineering and a software-development partner. Supplies ($10,000) cover concrete and consumables for prototype print tests. Personnel ($40,000) covers founding-team time and the first technical hire and is held at the 20% cap. Every line ties to a specific milestone in §11, and the Converge and software engagements are fixed-scope, bounding overrun risk. No applicant cost share is required or claimed."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T12:11:28.752Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T12:11:28.752Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T12:11:28.752Z'::timestamptz, true, '2026-08-10T12:11:28.752Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Budget', 2, NULL, '{}', '{"itemType":"spreadsheet","volumeName":"Budget","expertNotes":null}'::jsonb, 'a9d36876-0bbf-4aa6-8151-c52a4fb05e64', 16, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('07c7881f-c5d4-473c-8911-d1f1da1bab2f', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '17', 'Willingness-to-License Letter (from the IP-owning institution)', '{"version":2,"document_id":"907edc92-88ab-4d68-9e1d-5677ed4f6523","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"Willingness-to-License Letter","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.088Z","last_modified_at":"2026-08-10T12:11:27.088Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n09f2d248","type":"heading","content":{"level":1,"text":"Foundation — Statement of Intellectual-Property Ownership and Commitment"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n82f69e3f","type":"text_block","content":{"text":"Dayton, Ohio  ·  February 10, 2026"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n364c4952","type":"text_block","content":{"text":"Ohio Third Frontier — Technology Validation and Startup Fund, Review Committee"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n827770c1","type":"text_block","content":{"text":"Re: Ownership of and commitment to the technology proposed in Foundation’s TVSF application"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n2a3e0c68","type":"text_block","content":{"text":"Dear Members of the Review Committee:"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n9f16343b","type":"text_block","content":{"text":"Foundation is the owner of the intellectual property underpinning this application. The company holds two issued United States patents — U.S. Patent 11,273,574, “Scalable Three-Dimensional Printing Apparatus,” and U.S. Patent 10,307,959 B2, “Concrete Delivery System” — which together cover the rail-scalable print architecture and the concrete-delivery and nozzle-control mechanism at the core of Foundation’s residential 3D-printing system."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nf9d5a2f3","type":"text_block","content":{"text":"Because Foundation owns this technology outright, no external license is required to perform the proposed work or to commercialize the result: the company is free to, and hereby commits to, dedicate this patented technology to the TVSF project and to the Ohio market. Freedom-to-operate confirmation and a continuation strategy around the nozzle-gate control are included in the funded scope."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n276cd5f3","type":"text_block","content":{"text":"Foundation is prepared to execute the TVSF project upon award and to commercialize the validated technology from its Ohio base."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n5f37d162","type":"text_block","content":{"text":"Sincerely,"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"ndf71b560","type":"text_block","content":{"text":"Kate Ulepic, Chief Executive Officer · Foundation"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T12:11:28.840Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T12:11:28.840Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T12:11:28.840Z'::timestamptz, true, '2026-08-10T12:11:28.840Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Supporting Letters', 3, NULL, '{}', '{"itemType":"pdf","volumeName":"Supporting Letters","expertNotes":null}'::jsonb, 'eb81dd40-50a9-4ef0-9d8e-9c955c1f87bd', 17, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('471ae084-702f-4060-8a24-66edb42818c0', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '18', 'ESP Support Letter (from the EC)', '{"version":2,"document_id":"601e013e-32f9-4ba7-a47a-642423bcab19","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"ESP Support Letter","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.089Z","last_modified_at":"2026-08-10T12:11:27.089Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"nad468a94","type":"heading","content":{"level":1,"text":"Dayton/Miami Valley Entrepreneurs Center"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"nb4cbfb5e","type":"text_block","content":{"text":"Entrepreneurial Services Provider  ·  Dayton, Ohio"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"ncc6b30d2","type":"text_block","content":{"text":"February 10, 2026"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nb3126a5e","type":"text_block","content":{"text":"Ohio Third Frontier — Technology Validation and Startup Fund, Review Committee"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n665303de","type":"text_block","content":{"text":"Re: Entrepreneurial Services Provider Support for Foundation"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n076b38b5","type":"text_block","content":{"text":"Dear Members of the Review Committee:"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nbbc876f3","type":"text_block","content":{"text":"The Entrepreneurs’ Center is Foundation’s Entrepreneurial Services Provider, and I have worked closely with the founding team — Kate Ulepic, Conor Atkins, Connor Casey, and Will Curley — as their mentor and appointed shadow advisor on this TVSF build. I write in strong support of Foundation’s application."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n45f9de3a","type":"text_block","content":{"text":"Our engagement has been substantive. The Entrepreneurs’ Center helped Foundation structure and pressure-test the customer-discovery work with builders and subcontractors that produced the market evidence in this application; we built and stress-tested the financial model behind the company’s pro-forma and capital plan; and we advised directly on the scope, milestones, and budget of the proposed project."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n1dc84224","type":"text_block","content":{"text":"Foundation’s 3D-printed-foundation technology addresses a real, quantified, and timely market need, and the founder team has been disciplined about validating before it scales — taking the printer to a beta prototype and owning its core patents. In our assessment the team is well-positioned to execute this validation project and to commercialize the result in Ohio, and the Entrepreneurs’ Center will continue to support Foundation through award and into commercialization."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n36e94de3","type":"text_block","content":{"text":"Sincerely,"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n3fe1122f","type":"text_block","content":{"text":"Paul Jackson, VP Strategic Programs · Entrepreneurs’ Center"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T12:11:28.900Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T12:11:28.900Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T12:11:28.900Z'::timestamptz, true, '2026-08-10T12:11:28.900Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Supporting Letters', 3, NULL, '{}', '{"itemType":"pdf","volumeName":"Supporting Letters","expertNotes":null}'::jsonb, 'eb81dd40-50a9-4ef0-9d8e-9c955c1f87bd', 18, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('dc9be2c3-45b6-4050-914f-aa203834ae62', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '1', 'Abstract (public; excluded from 7-page count; no trade secrets)', '{"version":2,"document_id":"13edace7-8a11-4846-a069-f0dacefd8867","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"Abstract (public; excluded from 7-page count; no trade secrets)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.039Z","last_modified_at":"2026-08-10T12:11:27.040Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n1761a34b","type":"heading","content":{"level":1,"text":"Abstract"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n269eceb2","type":"text_block","content":{"text":"Residential foundations are still formed with temporary wooden or aluminum formwork that must be built, set, stripped, repaired, and cleaned for reuse — a labor-intensive, weather-exposed cycle that on a typical 2,100 sq ft Ohio home costs $20,000–$25,000 and roughly 336 labor hours. Foundation 3D-prints the foundation-wall shape directly from a downloaded plan, using common, locally sourced concrete instead of proprietary mortar and an external gate that controls flow at the nozzle for clean, consistent layers. This cuts foundation formwork to about $10,600 and ~25 labor hours — roughly 47% of the cost and eleven days per home. Foundation is an Ohio company (Dayton region) at TRL 6–7 with a beta prototype in progress; this $200,000 TVSF project validates a production-representative printer and third-party performance data that de-risk entry into a ~$2.3B U.S. concrete-formwork opportunity within an $846B single-family construction market — a 3D-construction-printing category now growing on the order of 80% per year and advance Ohio’s housing-affordability and advanced-manufacturing agendas."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T16:23:16.447Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'final', '2026-08-10T16:23:16.447Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T16:23:16.447Z'::timestamptz, true, '2026-08-10T16:23:16.447Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 1, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('60f3e18c-1ebb-4395-a798-31320baf4c5d', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '13', '12. Budget: Table & Narrative (ask <= $200k; Personnel <= 20%; no cost share; narrate every line)', '{"version":2,"document_id":"fbbfcf75-1023-4147-91a8-fc92eaef7892","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"12. Budget: Table & Narrative (ask <= $200k; Personnel <= 20%; no cost share; narrate every line)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.059Z","last_modified_at":"2026-08-10T12:11:27.059Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n1c87910f","type":"heading","content":{"level":1,"text":"12. Budget: Table and Narrative"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n6a8c95bd","type":"text_block","content":{"text":"Foundation’s $200,000 TVSF budget is presented in full in the Budget volume and is fully compliant with the Round-45 rules: the OTF ask is exactly $200,000, Personnel is within the 20% cap ($40,000), and no applicant cost share is required or claimed. The largest line, Equipment ($120,000), funds the COTS and specialized printer/delivery parts for the beta prototype built with Converge; Purchased Services ($30,000) covers Converge’s engineering and a software-development partner; Supplies ($10,000) cover concrete and consumables for prototype print tests; and Personnel ($40,000) covers founding-team time and the first technical hire. Every line ties to a specific project milestone, and the Converge and software engagements are fixed-scope, bounding overrun risk."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T12:11:28.558Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T12:11:28.558Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T12:11:28.558Z'::timestamptz, true, '2026-08-10T12:11:28.558Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 13, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('beee1b87-55bd-40d6-9316-214dfd105970', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '14', '13. Next Steps (no exit language)', '{"version":2,"document_id":"00d9bdae-dcc1-436e-b44c-991493efd045","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"13. Next Steps (no exit language)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.059Z","last_modified_at":"2026-08-10T12:11:27.059Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n6725e7f6","type":"heading","content":{"level":1,"text":"13. Next Steps"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n0fd311f4","type":"text_block","content":{"text":"Immediately upon award, Foundation will execute the Converge development engagement and hire the first technician/operator, then engineer and assemble the beta printer and delivery/gate (Months 1–8). In parallel it will advance the $1.8M equity round and confirm the independent test lab and partner-builder demonstration sites so third-party validation can proceed on schedule."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n0c8b8d93","type":"text_block","content":{"text":"On completion, Foundation exits with a production-representative printer, an independent structural and throughput validation report, and a partner-ready pilot printer. Those assets convert discovery-stage builder relationships into paid pilots and price the equity round on validated performance — the path from this TVSF validation to first commercial pilots runs through the 14-month plan."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T12:11:28.618Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T12:11:28.618Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T12:11:28.618Z'::timestamptz, true, '2026-08-10T12:11:28.618Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 14, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('f215c8fa-9750-4e3e-bfa7-4070b387ec38', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '5', '4. Commercialization Strategy (open with the SAM)', '{"version":2,"document_id":"e256f457-6596-4442-b595-9ab721750cec","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"4. Commercialization Strategy (open with the SAM)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.048Z","last_modified_at":"2026-08-10T12:11:27.048Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n6c6db837","type":"heading","content":{"level":1,"text":"4. Commercialization and Market Entry Strategy"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"nba049fff","type":"text_block","content":{"text":"The residential-construction market adopts new methods cautiously and on proof, and its buyers are local and fragmented, with trust, portability, and cost as the primary barriers. Foundation fits the existing subcontractor workflow and sells “printing as a service” to general contractors and developers rather than selling a machine — lowering the buyer’s barrier to a per-job operating decision. Because the system runs on common local ready-mix, a builder adopts Foundation without re-qualifying a proprietary mortar or changing supplier — a materially lower switching cost than ICON, COBOD, or Apis Cor impose."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nad3de423","type":"text_block","content":{"text":"Market entry pairs non-dilutive TVSF and SBIR Phase I with partnerships with local schools and builders for demonstrations and training; the path is demos/tours → paid pilot → repeat jobs with the same builders. The category tailwind is real — the U.S. 3D-construction-printing market is growing on the order of 80% per year and the largest national homebuilder has already invested in the space — so Foundation’s go-to-market rides validated demand. The market-size argument is established in Q1 and not repeated here; this answer works with the Q6 business model and the Q7 capital plan."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 2, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T16:18:55.469Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', NULL, NULL, 'final', '2026-08-10T16:18:55.469Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T16:18:55.469Z'::timestamptz, true, '2026-08-10T16:18:55.469Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 5, 'human_edit') ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('479950eb-7624-440f-b4f2-952659dab92b', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '6', '5. Intellectual Property (licensed IP + compare vs alternatives)', '{"version":2,"document_id":"7d382f6e-5af0-452e-8152-cd3d749644c0","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"5. Intellectual Property (licensed IP + compare vs alternatives)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.050Z","last_modified_at":"2026-08-10T12:11:27.050Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n148c1d35","type":"heading","content":{"level":1,"text":"5. IP Position"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n8cb68133","type":"text_block","content":{"text":"Foundation’s approach is anchored by two issued U.S. patents that the company owns: U.S. Patent 11,273,574, “Scalable Three-Dimensional Printing Apparatus,” covering the scalable gantry/rail print architecture, and U.S. Patent 10,307,959 B2, “Concrete Delivery System,” covering the concrete delivery and nozzle-control mechanism. Together they protect the two core differentiators — the rail-scalable printer and the externally gated, local-concrete delivery path — against the proprietary-mortar and mortar-extrusion approaches competing printers rely on. Freedom-to-operate confirmation and a continuation strategy around the nozzle-gate control are part of the funded work, extending the portfolio as the beta prototype matures."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T12:11:27.792Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T12:11:27.792Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T12:11:27.792Z'::timestamptz, true, '2026-08-10T12:11:27.792Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 6, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('1b156bfb-6e68-4601-a37d-1875c3874e98', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '7', '6. Business Model & Pro-forma P&L (native table 2027-2031; mandatory TVSF revenue row)', '{"version":2,"document_id":"e994497f-4ac5-4ddc-b1b9-cf4c292666a3","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"6. Business Model & Pro-forma P&L (native table 2027-2031; mandatory TVSF revenue row)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.051Z","last_modified_at":"2026-08-10T12:11:27.051Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n9b04061a","type":"heading","content":{"level":1,"text":"6. Business Model"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n1089bdf1","type":"text_block","content":{"text":"Foundation forms a joint venture on each project, programs and prepares the print, and charges per cubic yard of concrete placed — approximately $20,000 in total price per job at a contribution margin of about 37.5%. Printing-as-a-service keeps the capital with Foundation and lowers the builder’s barrier to adoption, and gross margin expands as printer utilization rises across repeat jobs. The abbreviated pro-forma below uses the required TVSF categories without modification; figures are directional and in $1,000s."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"nbbaa1378","type":"table","content":{"headers":[{"text":"($1,000s)","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"2027","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"2028","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"2029","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"2030","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}},{"text":"2031","style":{"bg":"#1F4E79","fg":"#FFFFFF","bold":true}}],"rows":[[{"text":"Revenues"},{"text":""},{"text":""},{"text":""},{"text":""},{"text":""}],[{"text":"  Print-as-a-service (per job)"},{"text":"120"},{"text":"700"},{"text":"2,400"},{"text":"6,300"},{"text":"13,500"}],[{"text":"  Licensing"},{"text":"0"},{"text":"0"},{"text":"0"},{"text":"0"},{"text":"0"}],[{"text":"  TVSF"},{"text":"200"},{"text":"0"},{"text":"0"},{"text":"0"},{"text":"0"}],[{"text":"  Other"},{"text":"0"},{"text":"0"},{"text":"0"},{"text":"0"},{"text":"0"}],[{"text":"  Total revenues","style":{"bg":"#DCE6F1","bold":true}},{"text":"320","style":{"bg":"#DCE6F1","bold":true}},{"text":"700","style":{"bg":"#DCE6F1","bold":true}},{"text":"2,400","style":{"bg":"#DCE6F1","bold":true}},{"text":"6,300","style":{"bg":"#DCE6F1","bold":true}},{"text":"13,500","style":{"bg":"#DCE6F1","bold":true}}],[{"text":"Production Expenses"},{"text":""},{"text":""},{"text":""},{"text":""},{"text":""}],[{"text":"  Cost of Goods Sold"},{"text":"75"},{"text":"438"},{"text":"1,500"},{"text":"3,940"},{"text":"8,440"}],[{"text":"  Gross profit","style":{"bg":"#DCE6F1","bold":true}},{"text":"245","style":{"bg":"#DCE6F1","bold":true}},{"text":"262","style":{"bg":"#DCE6F1","bold":true}},{"text":"900","style":{"bg":"#DCE6F1","bold":true}},{"text":"2,360","style":{"bg":"#DCE6F1","bold":true}},{"text":"5,060","style":{"bg":"#DCE6F1","bold":true}}],[{"text":"Other Expenses"},{"text":""},{"text":""},{"text":""},{"text":""},{"text":""}],[{"text":"  R & D, including IP"},{"text":"350"},{"text":"600"},{"text":"900"},{"text":"1,300"},{"text":"1,700"}],[{"text":"  SG&A"},{"text":"200"},{"text":"450"},{"text":"850"},{"text":"1,500"},{"text":"2,300"}],[{"text":"  Other"},{"text":"0"},{"text":"0"},{"text":"0"},{"text":"0"},{"text":"0"}],[{"text":"  Total other expenses","style":{"bg":"#DCE6F1","bold":true}},{"text":"550","style":{"bg":"#DCE6F1","bold":true}},{"text":"1,050","style":{"bg":"#DCE6F1","bold":true}},{"text":"1,750","style":{"bg":"#DCE6F1","bold":true}},{"text":"2,800","style":{"bg":"#DCE6F1","bold":true}},{"text":"4,000","style":{"bg":"#DCE6F1","bold":true}}],[{"text":"Net profit","style":{"bg":"#DCE6F1","bold":true}},{"text":"(305)","style":{"bg":"#DCE6F1","bold":true}},{"text":"(788)","style":{"bg":"#DCE6F1","bold":true}},{"text":"(850)","style":{"bg":"#DCE6F1","bold":true}},{"text":"(440)","style":{"bg":"#DCE6F1","bold":true}},{"text":"1,060","style":{"bg":"#DCE6F1","bold":true}}],[{"text":"Equity Investment","style":{"bg":"#DCE6F1","bold":true}},{"text":"1,800","style":{"bg":"#DCE6F1","bold":true}},{"text":"0","style":{"bg":"#DCE6F1","bold":true}},{"text":"0","style":{"bg":"#DCE6F1","bold":true}},{"text":"0","style":{"bg":"#DCE6F1","bold":true}},{"text":"0","style":{"bg":"#DCE6F1","bold":true}}]]},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"ne261a644","type":"caption","content":{"prefix":"Figure","number":2,"text":"Foundation pro-forma, 2027–2031 ($1,000s) — the per-job printing-as-a-service model; margin expands as printer utilization rises."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T12:11:27.896Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T12:11:27.896Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T12:11:27.896Z'::timestamptz, true, '2026-08-10T12:11:27.896Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 7, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('9248b6c0-1f10-400c-9899-2659ac4b87ca', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '8', '7. Current Financial Stage', '{"version":2,"document_id":"e6d2047f-4bfa-47f7-9c25-ee3c3f2ad157","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"7. Current Financial Stage","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.053Z","last_modified_at":"2026-08-10T12:11:27.053Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n3ffb314b","type":"heading","content":{"level":1,"text":"7. Current Financial Stage"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n94bf9e18","type":"text_block","content":{"text":"Foundation is pre-seed. The capital plan pairs $200,000 in non-dilutive TVSF and $150,000 in SBIR Phase I — directed at R&D and the beta prototype — with a targeted equity round of $1.8M or more. The non-dilutive grants exist to prove the market and de-risk the technology first, so the equity raise is priced on validated performance rather than on a concept. Equity investment is critical to scaling beyond the first printer; TVSF is the near-term unlock for the validated beta prototype that makes the round investable."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T12:11:27.987Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T12:11:27.987Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T12:11:27.987Z'::timestamptz, true, '2026-08-10T12:11:27.987Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 8, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('fd8f5843-85df-45c3-81c8-3cb5104d2269', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '4', '3. Development Stage & Timeline (native Gantt/timeline table; state TRL)', '{"version":2,"document_id":"882f0031-4959-428a-ae80-fd2a09a5be7f","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"3. Development Stage & Timeline (native Gantt/timeline table; state TRL)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.047Z","last_modified_at":"2026-08-10T12:11:27.047Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n92c8ad75","type":"heading","content":{"level":1,"text":"3. Development Stage and Timeline"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"nc5978f33","type":"text_block","content":{"text":"The system is at TRL 6–7 with an MVP in the beta-prototype phase: Foundation has demonstrated the rail-scalable print architecture and the externally gated, local-concrete delivery path, driven by customer requirements for rapid deployment, reduced labor, structural reliability, and locally sourced materials. This 14-month TVSF-anchored plan takes the system to a production-representative printer with independent performance validation; it maps one-for-one to the Q11 milestone table."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true},{"id":"n66361dc9","type":"chart","content":{"chart_type":"gantt","categories":["Hire core team","R&D with Converge","Beta prototype build","Third-party validation","First printer build"],"series":[{"name":"Start month","data":[1,3,6,9,11]},{"name":"End month","data":[2,4,8,14,14]}],"title":"Foundation TVSF 14-Month Project Gantt"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n91d70dda","type":"caption","content":{"prefix":"Figure","number":1,"text":"TVSF 14-month project Gantt — each milestone by month, mapping one-for-one to the Q11 Project Plan table."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T12:11:27.653Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T12:11:27.653Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T12:11:27.653Z'::timestamptz, true, '2026-08-10T12:11:27.653Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 4, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('7ee6cde2-9451-47e3-87b3-b36100bb1c00', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '9', '8. Economic Impact on Ohio', '{"version":2,"document_id":"33e01fdc-ef80-4591-930a-8944d9694992","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"8. Economic Impact on Ohio","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.054Z","last_modified_at":"2026-08-10T12:11:27.054Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"nb14bf20b","type":"heading","content":{"level":1,"text":"8. Economic Impact on State of Ohio"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"n62c99927","type":"text_block","content":{"text":"Foundation is Ohio-based and Ohio-building, headquartered in the Dayton region. It lowers the cost of new single-family homes in a state facing a supply gap, supports builder margins, and creates skilled advanced-manufacturing and print-operator jobs. By partnering with local schools and builders for demonstrations and training, Foundation seeds a regional workforce pipeline, and because the system prints with common, locally batched concrete it keeps concrete spend with local ready-mix suppliers rather than out-of-state proprietary-mortar vendors — compounding the in-state economic return of every job and anchoring a construction-technology cluster around Foundation’s Ohio-owned IP."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T12:11:28.055Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T12:11:28.055Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T12:11:28.055Z'::timestamptz, true, '2026-08-10T12:11:28.055Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 9, NULL) ON CONFLICT DO NOTHING;
INSERT INTO proposal_sections (id, proposal_id, section_number, title, content, page_allocation, status, assigned_to, requirement_ids, ai_confidence, version, created_at, updated_at, last_modified_by, editing_by, editing_since, completed_stage, completed_at, accepted_by, accepted_at, is_locked, locked_at, locked_by, volume_name, volume_number, section_type, tags, meta, artifact_id, sort_index, content_source) VALUES ('5e2008fb-ef39-49c0-bab3-043bc29b48c8', 'bbd6a058-3299-4b98-96e0-1e07e43aa1c4', '11', '10. ESP Engagement (the Entrepreneurs Center)', '{"version":2,"document_id":"0617dd38-aee3-4cc9-aa0e-e129c8981c93","canvas":{"format":"letter","width":612,"height":792,"margins":{"top":54,"right":54,"bottom":54,"left":54},"header":{"template":"Foundation — Ohio Third Frontier TVSF","height":26,"font":{"family":"Times New Roman","size":9}},"footer":{"template":"Foundation — TVSF Application (confidential)        Page {n} of {N}","height":26,"font":{"family":"Times New Roman","size":9}},"font_default":{"family":"Times New Roman","size":11},"line_spacing":1.06,"max_pages":7,"max_slides":null},"metadata":{"title":"10. ESP Engagement (the Entrepreneurs Center)","volume_id":"","required_item_id":"","proposal_id":"bbd6a058-3299-4b98-96e0-1e07e43aa1c4","solicitation_id":"","created_at":"2026-08-10T12:11:27.056Z","last_modified_at":"2026-08-10T12:11:27.056Z","last_modified_by":"system","version_number":1,"status":"ai_drafted"},"nodes":[{"id":"n98350504","type":"heading","content":{"level":1,"text":"10. ESP Engagement"},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":false},{"id":"nb82408d8","type":"text_block","content":{"text":"Foundation is mentored by the Entrepreneurs’ Center, with Paul Jackson (VP Strategic Programs) as its primary contact and an appointed shadow admin over the Foundation workspace and this TVSF build. The Entrepreneurs’ Center helped structure and pressure-test the customer-discovery work behind the market evidence in Q1 and Q4, built and stress-tested the financial model behind the Q6 pro-forma and the Q7 capital plan, and advised directly on the scope, milestones, and budget of this project. The engagement is ongoing through award and into commercialization — the EC will continue to support the equity raise, the third-party validation, and the conversion of demonstrations into paid pilots. The EC’s support letter accompanies this application."},"style":{},"provenance":{"source":"manual","drafted_at":"2026-08-10T00:00:00Z"},"history":[],"library_eligible":true}]}', NULL, 'approved', NULL, '{}', NULL, 1, '2026-08-10T03:15:31.432Z'::timestamptz, '2026-08-10T12:11:28.167Z'::timestamptz, NULL, NULL, NULL, 'draft', '2026-08-10T12:11:28.167Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', '2026-08-10T12:11:28.167Z'::timestamptz, true, '2026-08-10T12:11:28.167Z'::timestamptz, 'bd101904-582d-44db-ac2e-ce63eb341979', 'Proposal', 1, NULL, '{}', '{"itemType":"word_doc","volumeName":"Proposal","expertNotes":null}'::jsonb, '9d74fe2f-749b-4e08-ae8e-9dfada7832e9', 11, NULL) ON CONFLICT DO NOTHING;
